#include <string>
using namespace std;

// Lifecycle status of a single order.
enum class OrderStatus { PLACED, ASSIGNED, PICKED_UP, DELIVERED };

// A place that prepares orders, at a fixed location.
class Restaurant {
public:
    string restaurantId;  // unique id
    string name;             // display name
    double locationX;           // x coordinate
    double locationY;              // y coordinate

    Restaurant() : locationX(0.0), locationY(0.0) {}
    Restaurant(string id, string n, double x, double y) : restaurantId(id), name(n), locationX(x), locationY(y) {}
    // constructor stores id, name, and location
};

// A courier with a location, a capacity, and a current load.
class DeliveryPartner {
public:
    string partnerId;       // unique id
    string name;               // display name
    double locationX;             // x coordinate
    double locationY;                // y coordinate
    int capacity;                       // max concurrent orders this partner can carry
    int currentLoad;                       // orders currently being carried

    DeliveryPartner() : locationX(0.0), locationY(0.0), capacity(0), currentLoad(0) {}
    DeliveryPartner(string id, string n, double x, double y, int cap)
        : partnerId(id), name(n), locationX(x), locationY(y), capacity(cap), currentLoad(0) {}
    // constructor stores id, name, location, and capacity, starting with zero load

    bool hasSpareCapacity() { return currentLoad < capacity; } // true if room for one more
    void incrementLoad() { currentLoad++; }                       // take on one more order
    void decrementLoad() { currentLoad--; }                          // free up capacity after delivery
};

// One delivery request, tracking its restaurant, assigned partner, and lifecycle status.
class Order {
public:
    string orderId;              // unique id, e.g. ORD1
    string restaurantId;            // which restaurant prepared it
    string customerName;               // who receives it
    double destinationX;                  // x coordinate of the delivery address
    double destinationY;                     // y coordinate of the delivery address
    string assignedPartnerId;                   // which partner is carrying it, if any
    OrderStatus status;                            // current lifecycle state

    Order() : destinationX(0.0), destinationY(0.0), status(OrderStatus::PLACED) {}
    Order(string id, string restId, string customer, double destX, double destY)
        : orderId(id), restaurantId(restId), customerName(customer), destinationX(destX), destinationY(destY), status(OrderStatus::PLACED) {}
    // constructor stores every field and starts the order as PLACED
};

// Creates sequential, correctly-prefixed ids for orders.
class OrderIdFactory {
    int orderCounter = 0; // running id counter

public:
    string nextOrderId() {
        orderCounter++;                     // bump id counter
        return "ORD" + to_string(orderCounter); // e.g. ORD1
    }
};

