// Strategy interface: how a partner is chosen for an order.
interface DispatchStrategy {
    DeliveryPartner findPartner(Restaurant restaurant, java.util.Collection<DeliveryPartner> partners); // returns the chosen partner, or null if none qualifies
}

// Picks the closest partner to the restaurant among those with spare capacity.
class NearestPartnerDispatchStrategy implements DispatchStrategy {
    @Override
    public DeliveryPartner findPartner(Restaurant restaurant, java.util.Collection<DeliveryPartner> partners) {
        DeliveryPartner best = null;                                            // best candidate found so far
        double bestDistance = Double.MAX_VALUE;                                     // distance of the best candidate
        for (DeliveryPartner partner : partners) {                                    // scan every registered partner
            if (!partner.hasSpareCapacity()) continue;                                   // skip partners already full
            double dx = partner.getLocationX()-restaurant.getLocationX();                // x distance to the restaurant
            double dy = partner.getLocationY()-restaurant.getLocationY();                   // y distance to the restaurant
            double distance = Math.sqrt(dx * dx + dy * dy);                                     // straight line distance
            if (distance < bestDistance) {                                                        // closer than anything seen so far
                bestDistance = distance;                                                              // remember the new best distance
                best = partner;                                                                         // remember the new best partner
            }
        }
        return best; // the nearest partner with spare capacity, or null if none qualifies
    }
}

// Observer interface: reacts to dispatch lifecycle events.
interface DeliveryObserver {
    void onPartnerAssigned(Order order, DeliveryPartner partner);   // an order was successfully assigned
    void onDispatchFailed(String orderId, String reason);              // a dispatch attempt found no partner
    void onOrderDelivered(Order order);                                   // an order completed delivery
}

// Simple observer that prints events to the console.
class ConsoleDeliveryObserver implements DeliveryObserver {
    @Override
    public void onPartnerAssigned(Order order, DeliveryPartner partner) {
        System.out.println("Order " + order.getOrderId() + " assigned to " + partner.getPartnerId() + ", load now " + partner.getCurrentLoad());
    }

    @Override
    public void onDispatchFailed(String orderId, String reason) {
        System.out.println("Dispatch failed for " + orderId + ": " + reason);
    }

    @Override
    public void onOrderDelivered(Order order) {
        System.out.println("Order " + order.getOrderId() + " delivered");
    }
}

