using namespace std;

// Strategy interface: how a partner is chosen for an order.
class DispatchStrategy {
public:
    virtual DeliveryPartner* findPartner(Restaurant& restaurant, vector<DeliveryPartner*>& partners) = 0;
    virtual ~DispatchStrategy() {}
};

// Picks the closest partner to the restaurant among those with spare capacity.
class NearestPartnerDispatchStrategy : public DispatchStrategy {
public:
    DeliveryPartner* findPartner(Restaurant& restaurant, vector<DeliveryPartner*>& partners) override {
        DeliveryPartner* best = nullptr;                                          // best candidate found so far
        double bestDistance = 1e18;                                                  // distance of the best candidate
        for (auto* partner : partners) {                                               // scan every registered partner
            if (!partner->hasSpareCapacity()) continue;                                   // skip partners already full
            double dx = partner->locationX-restaurant.locationX;                          // x distance to the restaurant
            double dy = partner->locationY-restaurant.locationY;                             // y distance to the restaurant
            double distance = sqrt(dx * dx + dy * dy);                                           // straight line distance
            if (distance < bestDistance) {                                                          // closer than anything seen so far
                bestDistance = distance;                                                                // remember the new best distance
                best = partner;                                                                           // remember the new best partner
            }
        }
        return best; // the nearest partner with spare capacity, or nullptr if none qualifies
    }
};

// Observer interface: reacts to dispatch lifecycle events.
class DeliveryObserver {
public:
    virtual void onPartnerAssigned(const Order& order, const DeliveryPartner& partner) = 0;
    virtual void onDispatchFailed(const string& orderId, const string& reason) = 0;
    virtual void onOrderDelivered(const Order& order) = 0;
    virtual ~DeliveryObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleDeliveryObserver : public DeliveryObserver {
public:
    void onPartnerAssigned(const Order& order, const DeliveryPartner& partner) override {
        cout << "Order " << order.orderId << " assigned to " << partner.partnerId << ", load now " << partner.currentLoad << endl;
    }
    void onDispatchFailed(const string& orderId, const string& reason) override {
