// Custom exceptions for the realistic failure modes.
class NoPartnerAvailableException extends RuntimeException {
    public NoPartnerAvailableException(String msg) { super(msg); }
}
class InvalidOrderStateException extends RuntimeException {
    public InvalidOrderStateException(String msg) { super(msg); }
}
class PartnerCapacityExceededException extends RuntimeException {
    public PartnerCapacityExceededException(String msg) { super(msg); }
}

// The core dispatch engine tying every piece together.
class DeliveryDispatchService {
    private final java.util.Map<String, Restaurant> restaurants = new java.util.HashMap<>();          // restaurantId -> Restaurant
    private final java.util.Map<String, DeliveryPartner> partners = new java.util.HashMap<>();           // partnerId -> DeliveryPartner
    private final java.util.Map<String, Order> orders = new java.util.HashMap<>();                          // orderId -> Order
    private final DispatchStrategy strategy;                                                                   // how a partner is chosen
    private final java.util.List<DeliveryObserver> observers = new java.util.ArrayList<>();                       // listeners

    public DeliveryDispatchService(DispatchStrategy strategy) {
        this.strategy = strategy; // store the chosen dispatch algorithm
    }

    public void addRestaurant(Restaurant restaurant) { restaurants.put(restaurant.getRestaurantId(), restaurant); } // register a restaurant
    public void addPartner(DeliveryPartner partner) { partners.put(partner.getPartnerId(), partner); }                 // register a partner
    public void addObserver(DeliveryObserver observer) { observers.add(observer); }                                       // register a listener
    public Order placeOrder(Order order) { orders.put(order.getOrderId(), order); return order; }                           // register a new order

    // Assigns an order to the nearest partner with spare capacity, using the configured dispatch strategy.
    public synchronized Order dispatchOrder(String orderId) {
        Order order = orders.get(orderId);                                            // the order to dispatch
        Restaurant restaurant = restaurants.get(order.getRestaurantId());                // where it is being prepared
        DeliveryPartner partner = strategy.findPartner(restaurant, partners.values());     // ask the strategy for a partner
        if (partner == null) {                                                               // nobody qualifies
            for (DeliveryObserver obs : observers) obs.onDispatchFailed(orderId, "No partner with spare capacity");
            throw new NoPartnerAvailableException("No partner available for order " + orderId);
        }
        partner.incrementLoad();                                                                // take on this order
        order.setAssignedPartnerId(partner.getPartnerId());                                        // record the assignment
        order.setStatus(OrderStatus.ASSIGNED);                                                        // advance the lifecycle
        for (DeliveryObserver obs : observers) obs.onPartnerAssigned(order, partner);                    // notify
        return order; // hand back the now-assigned order
    }

    // Directly assigns an order to a specific partner, still capacity-checked.
    public synchronized Order assignManually(String orderId, String partnerId) {
        Order order = orders.get(orderId);                                        // the order to assign
        DeliveryPartner partner = partners.get(partnerId);                           // the requested partner
        if (!partner.hasSpareCapacity()) {                                             // this partner cannot take more
            throw new PartnerCapacityExceededException("Partner " + partnerId + " is already at capacity");
        }
        partner.incrementLoad();                                                          // take on this order
        order.setAssignedPartnerId(partnerId);                                              // record the assignment
        order.setStatus(OrderStatus.ASSIGNED);                                                // advance the lifecycle
        for (DeliveryObserver obs : observers) obs.onPartnerAssigned(order, partner);            // notify
        return order; // hand back the now-assigned order
    }

    // Transitions an assigned order to picked up.
    public Order markPickedUp(String orderId) {
        Order order = orders.get(orderId);                                     // the order to advance
        if (order.getStatus() != OrderStatus.ASSIGNED) {                          // must currently be assigned
            throw new InvalidOrderStateException("Order " + orderId + " is not assigned, cannot be picked up");
        }
        order.setStatus(OrderStatus.PICKED_UP); // advance the lifecycle
        return order; // hand back the updated order
    }

    // Transitions a picked-up order to delivered, freeing the partner's capacity.
    public Order markDelivered(String orderId) {
        Order order = orders.get(orderId);                                        // the order to advance
        if (order.getStatus() != OrderStatus.PICKED_UP) {                            // must currently be picked up
            throw new InvalidOrderStateException("Order " + orderId + " is not picked up, cannot be delivered");
        }
        DeliveryPartner partner = partners.get(order.getAssignedPartnerId());           // the carrying partner
        partner.decrementLoad();                                                          // free up their capacity
        order.setStatus(OrderStatus.DELIVERED);                                             // advance the lifecycle
        for (DeliveryObserver obs : observers) obs.onOrderDelivered(order);                    // notify
        return order; // hand back the updated order
    }
}

