#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class NoPartnerAvailableException : public runtime_error {
public: NoPartnerAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidOrderStateException : public runtime_error {
public: InvalidOrderStateException(const string& msg) : runtime_error(msg) {}
};
class PartnerCapacityExceededException : public runtime_error {
public: PartnerCapacityExceededException(const string& msg) : runtime_error(msg) {}
};

// The core dispatch engine tying every piece together.
class DeliveryDispatchService {
    map<string, Restaurant> restaurants;               // restaurantId -> Restaurant
    map<string, DeliveryPartner> partners;                // partnerId -> DeliveryPartner
    map<string, Order> orders;                               // orderId -> Order
    shared_ptr<DispatchStrategy> strategy;                      // how a partner is chosen
    vector<shared_ptr<DeliveryObserver>> observers;                // listeners

public:
    DeliveryDispatchService(shared_ptr<DispatchStrategy> s) : strategy(s) {} // store the chosen dispatch algorithm

    void addRestaurant(Restaurant restaurant) { restaurants[restaurant.restaurantId] = restaurant; } // register a restaurant
    void addPartner(DeliveryPartner partner) { partners[partner.partnerId] = partner; }                 // register a partner
    void addObserver(shared_ptr<DeliveryObserver> observer) { observers.push_back(observer); }             // register a listener
    Order placeOrder(Order order) { orders[order.orderId] = order; return order; }                            // register a new order

    Order dispatchOrder(string orderId) {
        Order& order = orders.at(orderId);                                                // the order to dispatch
        Restaurant& restaurant = restaurants.at(order.restaurantId);                         // where it is being prepared
        vector<DeliveryPartner*> pointers;                                                      // strategy needs pointers so it can mutate load
        for (auto& pair : partners) pointers.push_back(&pair.second);                              // collect every registered partner
        DeliveryPartner* partner = strategy->findPartner(restaurant, pointers);                       // ask the strategy for a partner
        if (partner == nullptr) {                                                                       // nobody qualifies
            for (auto& obs : observers) obs->onDispatchFailed(orderId, "No partner with spare capacity");
            throw NoPartnerAvailableException("No partner available for order " + orderId);
        }
        partner->incrementLoad();                                                                          // take on this order
        order.assignedPartnerId = partner->partnerId;                                                         // record the assignment
        order.status = OrderStatus::ASSIGNED;                                                                    // advance the lifecycle
        for (auto& obs : observers) obs->onPartnerAssigned(order, *partner);                                        // notify
        return order; // hand back the now-assigned order
    }

    Order assignManually(string orderId, string partnerId) {
        Order& order = orders.at(orderId);                                    // the order to assign
        DeliveryPartner& partner = partners.at(partnerId);                       // the requested partner
        if (!partner.hasSpareCapacity()) {                                          // this partner cannot take more
            throw PartnerCapacityExceededException("Partner " + partnerId + " is already at capacity");
        }
        partner.incrementLoad();                                                       // take on this order
        order.assignedPartnerId = partnerId;                                             // record the assignment
        order.status = OrderStatus::ASSIGNED;                                              // advance the lifecycle
        for (auto& obs : observers) obs->onPartnerAssigned(order, partner);                   // notify
        return order; // hand back the now-assigned order
    }

    Order markPickedUp(string orderId) {
        Order& order = orders.at(orderId);                              // the order to advance
        if (order.status != OrderStatus::ASSIGNED) {                       // must currently be assigned
            throw InvalidOrderStateException("Order " + orderId + " is not assigned, cannot be picked up");
        }
        order.status = OrderStatus::PICKED_UP; // advance the lifecycle
        return order; // hand back the updated order
    }

    Order markDelivered(string orderId) {
        Order& order = orders.at(orderId);                                 // the order to advance
        if (order.status != OrderStatus::PICKED_UP) {                         // must currently be picked up
            throw InvalidOrderStateException("Order " + orderId + " is not picked up, cannot be delivered");
        }
        DeliveryPartner& partner = partners.at(order.assignedPartnerId);         // the carrying partner
        partner.decrementLoad();                                                   // free up their capacity
        order.status = OrderStatus::DELIVERED;                                        // advance the lifecycle
        for (auto& obs : observers) obs->onOrderDelivered(order);                        // notify
        return order; // hand back the updated order
    }
};

