        service.addPartner(new DeliveryPartner("P3", "Partner Three", 1.0, 1.0, 1));

        Order o1 = service.placeOrder(new Order(factory.nextOrderId(), "R1", "Alice", 3.0, 3.0));
        service.dispatchOrder(o1.getOrderId());

        Order o2 = service.placeOrder(new Order(factory.nextOrderId(), "R1", "Bob", 4.0, 4.0));
        service.dispatchOrder(o2.getOrderId());

        Order o3 = service.placeOrder(new Order(factory.nextOrderId(), "R1", "Carol", 5.0, 1.0));
        service.dispatchOrder(o3.getOrderId());

        Order o4 = service.placeOrder(new Order(factory.nextOrderId(), "R1", "Dave", 6.0, 6.0));
        service.dispatchOrder(o4.getOrderId());

        Order o5 = service.placeOrder(new Order(factory.nextOrderId(), "R1", "Eve", 7.0, 7.0));
        service.dispatchOrder(o5.getOrderId());

