#include <memory>
#include <cmath>
#include <stdexcept>
using namespace std;

enum class OrderStatus { PLACED, ASSIGNED, PICKED_UP, DELIVERED };

class Restaurant {
public:
    string restaurantId;
    string name;
    double locationX;
    double locationY;

    Restaurant() : locationX(0.0), locationY(0.0) {}
    Restaurant(string id, string n, double x, double y) : restaurantId(id), name(n), locationX(x), locationY(y) {}
};

class DeliveryPartner {
public:
    string partnerId;
    string name;
    double locationX;
    double locationY;
    int capacity;
    int currentLoad;

    DeliveryPartner() : locationX(0.0), locationY(0.0), capacity(0), currentLoad(0) {}
    DeliveryPartner(string id, string n, double x, double y, int cap)
        : partnerId(id), name(n), locationX(x), locationY(y), capacity(cap), currentLoad(0) {}

    bool hasSpareCapacity() { return currentLoad < capacity; }
    void incrementLoad() { currentLoad++; }
    void decrementLoad() { currentLoad--; }
};

class Order {
public:
    string orderId;
    string restaurantId;
    string customerName;
    double destinationX;
    double destinationY;
    string assignedPartnerId;
    OrderStatus status;

    Order() : destinationX(0.0), destinationY(0.0), status(OrderStatus::PLACED) {}
    Order(string id, string restId, string customer, double destX, double destY)
        : orderId(id), restaurantId(restId), customerName(customer), destinationX(destX), destinationY(destY), status(OrderStatus::PLACED) {}
};

class OrderIdFactory {
    int orderCounter = 0;

public:
    string nextOrderId() {
        orderCounter++;
        return "ORD" + to_string(orderCounter);
    }
};

class DispatchStrategy {
public:
    virtual DeliveryPartner* findPartner(Restaurant& restaurant, vector<DeliveryPartner*>& partners) = 0;
    virtual ~DispatchStrategy() {}
};

class NearestPartnerDispatchStrategy : public DispatchStrategy {
public:
    DeliveryPartner* findPartner(Restaurant& restaurant, vector<DeliveryPartner*>& partners) override {
        DeliveryPartner* best = nullptr;
        double bestDistance = 1e18;
        for (auto* partner : partners) {
            if (!partner->hasSpareCapacity()) continue;
            double dx = partner->locationX-restaurant.locationX;
            double dy = partner->locationY-restaurant.locationY;
            double distance = sqrt(dx * dx + dy * dy);
            if (distance < bestDistance) {
                bestDistance = distance;
                best = partner;
            }
        }
        return best;
    }
};

class DeliveryObserver {
public:
    virtual void onPartnerAssigned(const Order& order, const DeliveryPartner& partner) = 0;
    virtual void onDispatchFailed(const string& orderId, const string& reason) = 0;
    virtual void onOrderDelivered(const Order& order) = 0;
    virtual ~DeliveryObserver() {}
};

class ConsoleDeliveryObserver : public DeliveryObserver {
public:
    void onPartnerAssigned(const Order& order, const DeliveryPartner& partner) override {
        cout << "Order " << order.orderId << " assigned to " << partner.partnerId << ", load now " << partner.currentLoad << endl;
    }
    void onDispatchFailed(const string& orderId, const string& reason) override {
        cout << "Dispatch failed for " << orderId << ": " << reason << endl;
    }
    void onOrderDelivered(const Order& order) override {
        cout << "Order " << order.orderId << " delivered" << endl;
    }
};

class NoPartnerAvailableException : public runtime_error {
public: NoPartnerAvailableException(const string& msg) : runtime_error(msg) {}
};
class InvalidOrderStateException : public runtime_error {
public: InvalidOrderStateException(const string& msg) : runtime_error(msg) {}
};
class PartnerCapacityExceededException : public runtime_error {
public: PartnerCapacityExceededException(const string& msg) : runtime_error(msg) {}
};

class DeliveryDispatchService {
    map<string, Restaurant> restaurants;
    map<string, DeliveryPartner> partners;
    map<string, Order> orders;
    shared_ptr<DispatchStrategy> strategy;
    vector<shared_ptr<DeliveryObserver>> observers;

public:
    DeliveryDispatchService(shared_ptr<DispatchStrategy> s) : strategy(s) {}

    void addRestaurant(Restaurant restaurant) { restaurants[restaurant.restaurantId] = restaurant; }
    void addPartner(DeliveryPartner partner) { partners[partner.partnerId] = partner; }
    void addObserver(shared_ptr<DeliveryObserver> observer) { observers.push_back(observer); }
    Order placeOrder(Order order) { orders[order.orderId] = order; return order; }

    Order dispatchOrder(string orderId) {
        Order& order = orders.at(orderId);
        Restaurant& restaurant = restaurants.at(order.restaurantId);
        vector<DeliveryPartner*> pointers;
        for (auto& pair : partners) pointers.push_back(&pair.second);
        DeliveryPartner* partner = strategy->findPartner(restaurant, pointers);
        if (partner == nullptr) {
            for (auto& obs : observers) obs->onDispatchFailed(orderId, "No partner with spare capacity");
            throw NoPartnerAvailableException("No partner available for order " + orderId);
        }
        partner->incrementLoad();
        order.assignedPartnerId = partner->partnerId;
        order.status = OrderStatus::ASSIGNED;
        for (auto& obs : observers) obs->onPartnerAssigned(order, *partner);
        return order;
    }

    Order assignManually(string orderId, string partnerId) {
        Order& order = orders.at(orderId);
        DeliveryPartner& partner = partners.at(partnerId);
        if (!partner.hasSpareCapacity()) {
            throw PartnerCapacityExceededException("Partner " + partnerId + " is already at capacity");
        }
        partner.incrementLoad();
        order.assignedPartnerId = partnerId;
        order.status = OrderStatus::ASSIGNED;
        for (auto& obs : observers) obs->onPartnerAssigned(order, partner);
        return order;
    }

    Order markPickedUp(string orderId) {
        Order& order = orders.at(orderId);
        if (order.status != OrderStatus::ASSIGNED) {
            throw InvalidOrderStateException("Order " + orderId + " is not assigned, cannot be picked up");
        }
        order.status = OrderStatus::PICKED_UP;
        return order;
    }

    Order markDelivered(string orderId) {
        Order& order = orders.at(orderId);
        if (order.status != OrderStatus::PICKED_UP) {
            throw InvalidOrderStateException("Order " + orderId + " is not picked up, cannot be delivered");
        }
        DeliveryPartner& partner = partners.at(order.assignedPartnerId);
        partner.decrementLoad();
        order.status = OrderStatus::DELIVERED;
        for (auto& obs : observers) obs->onOrderDelivered(order);
        return order;
    }
};

int main() {
    DeliveryDispatchService service(make_shared<NearestPartnerDispatchStrategy>());
    service.addObserver(make_shared<ConsoleDeliveryObserver>());
